// Benchmarks ways to restore the node_modules cache on the CI runners. Run it from the workspace
// root after downloading, but not extracting, the node_modules cache to .build/node_modules_cache.
// Each restore variant writes to an empty target: on Windows a new Dev Drive, like the PR jobs.
// The results go to .build/nmb/results.{md,json} and to the job summary.
//
// NMB_ONLY=a,b runs only the named sections and variants, NMB_SKIP=a,b skips them.

import { spawnSync, type SpawnSyncOptions } from 'child_process';
import * as fs from 'fs';
import * as os from 'os';
import * as path from 'path';

const isWindows = process.platform === 'win32';
const isMac = process.platform === 'darwin';
const ws = process.cwd();
const temp = process.env.RUNNER_TEMP ?? os.tmpdir();
const work = path.join(ws, '.build', 'nmb');
const archiveTool = path.join(import.meta.dirname, 'archive.ts');
const todayArchive = path.join(ws, '.build', 'node_modules_cache', isWindows ? 'cache.7z' : 'node-modules.tzst');
const listFile = path.join(work, 'list.txt');
const store7z = path.join(work, 'store.7z');
const only = process.env.NMB_ONLY ? new Set(process.env.NMB_ONLY.split(',')) : undefined;
const skip = new Set(process.env.NMB_SKIP?.split(',') ?? []);

const BSDTAR = 'C:\\Windows\\System32\\tar.exe';
const GNUTAR = 'C:\\Program Files\\Git\\usr\\bin\\tar.exe';

const ARCHIVES = [
	{ name: 'plain', flags: '' },
	{ name: 'dedup', flags: 'dedup' },
	{ name: 'dedupbig', flags: 'dedupbig' },
	{ name: 'nomap', flags: 'nomap' },
	{ name: 'nocopilot', flags: 'nocopilot' },
	{ name: 'nomap-nocopilot', flags: 'nomap+nocopilot' },
	{ name: 'all', flags: 'dedup+nomap+nocopilot' },
];
const CONCURRENCY_SWEEP = [4, 8, 16, 32, 64];

interface Row {
	readonly group: string;
	readonly name: string;
	readonly seconds?: number;
	readonly bytes?: number;
	readonly detail?: string;
	readonly error?: string;
}

const rows: Row[] = [];
const environment: Record<string, string> = {};

//#region helpers

function selected(name: string): boolean {
	return !skip.has(name) && (!only || only.has(name));
}

function message(err: unknown): string {
	return err instanceof Error ? err.message : String(err);
}

interface RunOptions extends SpawnSyncOptions {
	readonly okCodes?: readonly number[];
	readonly capture?: boolean;
}

function run(command: string, args: readonly string[], options: RunOptions = {}): string {
	console.log(`$ ${command} ${args.join(' ')}`);
	const { okCodes = [0], capture = false, ...spawnOptions } = options;
	const result = spawnSync(command, args, {
		stdio: capture ? ['ignore', 'pipe', 'inherit'] : 'inherit',
		timeout: 40 * 60 * 1000,
		maxBuffer: 256 * 1024 * 1024,
		...spawnOptions,
	});
	if (result.error) {
		throw result.error;
	}
	if (!okCodes.includes(result.status ?? -1)) {
		throw new Error(`${path.basename(command)} exited with ${result.status ?? result.signal}`);
	}
	const output = result.stdout?.toString() ?? '';
	if (capture) {
		process.stdout.write(output);
	}
	return output;
}

function tryFirstLine(command: string, args: readonly string[]): string {
	const result = spawnSync(command, args, { encoding: 'utf8' });
	return `${result.stdout ?? ''}${result.stderr ?? ''}`.split(/\r?\n/).find(line => line.trim())?.trim() ?? 'n/a';
}

function shell(commandLine: string, cwd?: string): void {
	if (isWindows) {
		run('cmd', ['/d', '/s', '/c', `"${commandLine}"`], { cwd, windowsVerbatimArguments: true });
	} else {
		run('bash', ['-c', `set -eo pipefail; ${commandLine}`], { cwd });
	}
}

function pwsh(command: string, capture = false): string {
	return run('pwsh', ['-NoProfile', '-NonInteractive', '-Command', `$ErrorActionPreference = 'Stop'; $ProgressPreference = 'SilentlyContinue'; ${command}`], { capture });
}

function slash(file: string): string {
	return file.replace(/\\/g, '/');
}

function archive(name: string): string {
	return path.join(work, `${name}.tar.zst`);
}

function imageSource(name: string): string {
	return path.join(temp, isWindows ? `nmb-image-${name}.vhdx` : `nmb-image-${name}`);
}

function allocatedSize(file: string): number {
	const stat = fs.statSync(file);
	return isWindows || !stat.blocks ? stat.size : stat.blocks * 512;
}

function record(row: Row): void {
	rows.push(row);
	writeResults(false);
}

function recordSize(name: string, file: string): void {
	try {
		record({ group: 'size', name, bytes: allocatedSize(file) });
	} catch (err) {
		console.log(`::warning::no size for ${name}: ${message(err)}`);
	}
}

async function measure(group: string, name: string, fn: () => unknown): Promise<boolean> {
	console.log(`::group::[${group}] ${name}`);
	const start = performance.now();
	let detail: string | undefined;
	let error: string | undefined;
	try {
		const result = await fn();
		if (typeof result === 'string' && result) {
			detail = result;
		}
	} catch (err) {
		error = message(err);
	}
	const seconds = (performance.now() - start) / 1000;
	console.log('::endgroup::');
	console.log(`${error ? '::warning::' : ''}=> [${group}] ${name}: ${seconds.toFixed(1)}s${detail ? `, ${detail}` : ''}${error ? `, FAILED: ${error}` : ''}`);
	record({ group, name, seconds, detail, error });
	return !error;
}

function formatBytes(bytes: number | undefined): string {
	return bytes === undefined ? '' : `${(bytes / 1024 / 1024).toFixed(0)} MB`;
}

function writeResults(final: boolean): void {
	fs.mkdirSync(work, { recursive: true });
	fs.writeFileSync(path.join(work, 'results.json'), JSON.stringify({ platform: process.platform, environment, rows }, undefined, '\t'));
	const today = rows.find(row => row.group === 'restore' && row.name === 'today' && !row.error)?.seconds;
	const cell = (text: string) => text.replace(/\|/g, '\\|').replace(/\r?\n/g, ' ');
	const lines = [
		`## node_modules restore benchmark: ${process.platform}`,
		'',
		...Object.entries(environment).map(([key, value]) => `- ${key}: ${cell(value)}`),
		'',
		'| Group | Step | Seconds | vs today | Size | Details |',
		'| --- | --- | ---: | ---: | ---: | --- |',
		...rows.map(row => {
			const factor = row.group === 'restore' && today && row.seconds && !row.error ? `${(today / row.seconds).toFixed(1)}x` : '';
			return `| ${row.group} | ${cell(row.name)} | ${row.seconds?.toFixed(1) ?? ''} | ${factor} | ${formatBytes(row.bytes)} | ${row.error ? `**FAILED**: ${cell(row.error)}` : cell(row.detail ?? '')} |`;
		}),
	];
	fs.writeFileSync(path.join(work, 'results.md'), `${lines.join('\n')}\n`);
	if (final && process.env.GITHUB_STEP_SUMMARY) {
		fs.appendFileSync(process.env.GITHUB_STEP_SUMMARY, `${lines.join('\n')}\n`);
	}
}

function nodeModulesRoots(): string[] {
	const roots = new Set<string>();
	for (const line of fs.readFileSync(listFile, 'utf8').split(/\r?\n/)) {
		const parts = line.split('/');
		const index = parts.indexOf('node_modules');
		if (index !== -1) {
			roots.add(parts.slice(0, index + 1).join('/'));
		}
	}
	return [...roots];
}

//#endregion

//#region restore methods

function extractToday(dest: string): void {
	if (isWindows) {
		// .github/workflows/node_modules_cache/cache.ps1 extract
		run('7z', ['x', todayArchive, '-aoa', `-o${dest}`]);
	} else {
		// .github/workflows/node_modules_cache/cache.sh extract
		run('tar', ['--use-compress-program=zstd -d -T0', '-xf', todayArchive], { cwd: dest });
	}
}

function nodeExtract(name: string, dest: string, concurrency: number, decoder = 'cli'): string {
	const statsFile = path.join(work, 'extract-stats.json');
	fs.rmSync(statsFile, { force: true });
	run(process.execPath, [archiveTool, 'extract', '--archive', archive(name), '--dest', dest, '--concurrency', String(concurrency), '--decoder', decoder, '--stats', statsFile], {
		env: { ...process.env, UV_THREADPOOL_SIZE: String(Math.min(concurrency, 1024)) },
	});
	const stats = JSON.parse(fs.readFileSync(statsFile, 'utf8'));
	return `${stats.files} files + ${stats.hardlinks} hard links + ${stats.symlinks} symlinks, ${stats.dirs} folders, ${(stats.bytes / 1e9).toFixed(2)} GB`;
}

/**
 * Reads every file under `dir` with 16 reads in flight: the worst case for the images that
 * decompress files when they are read.
 */
async function readAll(dir: string): Promise<string> {
	const files = fs.readdirSync(dir, { recursive: true, withFileTypes: true })
		.filter(entry => entry.isFile())
		.map(entry => path.join(entry.parentPath, entry.name));
	let next = 0;
	let bytes = 0;
	await Promise.all(Array.from({ length: 16 }, async () => {
		while (next < files.length) {
			const data = await fs.promises.readFile(files[next++]);
			bytes += data.length;
		}
	}));
	return `${files.length} files, ${(bytes / 1e9).toFixed(2)} GB`;
}

function countArchive(file: string): string {
	const statsFile = path.join(work, 'count-stats.json');
	run(process.execPath, [archiveTool, 'count', '--archive', file, '--stats', statsFile]);
	return Object.entries(JSON.parse(fs.readFileSync(statsFile, 'utf8'))).map(([key, value]) => `${key}=${value}`).join(' ');
}

function transpile(): void {
	run(process.execPath, ['--experimental-strip-types', '--max-old-space-size=8192', './node_modules/gulp/bin/gulp.js', 'transpile-client-esbuild', 'transpile-extensions'], { cwd: ws });
}

//#endregion

//#region targets

function diskpart(lines: readonly string[]): void {
	const script = path.join(temp, 'nmb-diskpart.txt');
	fs.writeFileSync(script, `${lines.join('\r\n')}\r\n`);
	run('diskpart', ['/s', script]);
}

function createDevDrive(vhd: string, letter: string): string {
	fs.rmSync(vhd, { force: true });
	diskpart([`create vdisk file="${vhd}" maximum=102400 type=expandable`, `select vdisk file="${vhd}"`, 'attach vdisk', 'create partition primary', `assign letter=${letter}`]);
	pwsh(`Format-Volume -DriveLetter ${letter} -DevDrive -Confirm:$false -Force | Out-Null`);
	return `${letter}:\\`;
}

function attachVhd(vhd: string, letter: string): string {
	pwsh([
		`$disk = Mount-DiskImage -ImagePath '${vhd}' -NoDriveLetter -PassThru | Get-Disk`,
		'for ($i = 0; $i -lt 40 -and -not ($partition = $disk | Get-Partition | Where-Object Type -ne Reserved | Select-Object -First 1)); $i++) { Start-Sleep -Milliseconds 250 }',
		`$partition | Set-Partition -NewDriveLetter ${letter}`,
	].join('; '));
	return `${letter}:\\`;
}

function detachVhd(vhd: string): void {
	diskpart([`select vdisk file="${vhd}"`, 'detach vdisk']);
}

interface Target {
	readonly dest: string;
	readonly vhd?: string;
}

let targets = 0;

function newTarget(name: string): Target {
	if (isWindows) {
		const vhd = path.join(temp, `nmb-target-${++targets}.vhdx`);
		return { dest: createDevDrive(vhd, 'X'), vhd };
	}
	const dest = path.join(temp, 'nmb-target', name.replace(/[^\w.-]+/g, '-'));
	fs.rmSync(dest, { recursive: true, force: true });
	fs.mkdirSync(dest, { recursive: true });
	return { dest };
}

function dropTarget(target: Target, keepAs: string | undefined): void {
	if (keepAs) {
		fs.rmSync(keepAs, { recursive: true, force: true });
	}
	if (target.vhd) {
		detachVhd(target.vhd);
		if (keepAs) {
			fs.renameSync(target.vhd, keepAs);
		} else {
			fs.rmSync(target.vhd, { force: true });
		}
	} else if (keepAs) {
		fs.renameSync(target.dest, keepAs);
	} else {
		fs.rmSync(target.dest, { recursive: true, force: true });
	}
}

interface VariantOptions {
	readonly keepAs?: string;
	readonly before?: (dest: string) => void;
	readonly after?: (dest: string) => void;
}

async function variant(name: string, restore: (dest: string) => unknown, options: VariantOptions = {}): Promise<void> {
	if (!selected(name)) {
		return;
	}
	let target: Target;
	try {
		target = newTarget(name);
		options.before?.(target.dest);
		if (!isWindows) {
			// Don't let the writes of the previous variant compete with this one
			run('sync', []);
		}
	} catch (err) {
		record({ group: 'restore', name, error: `setup: ${message(err)}` });
		return;
	}
	await measure('restore', name, () => restore(target.dest));
	try {
		options.after?.(target.dest);
		dropTarget(target, options.keepAs);
	} catch (err) {
		console.log(`::warning::cleanup of ${name} failed: ${message(err)}`);
	}
}

function defenderExclusion(dest: string, add: boolean): void {
	pwsh(`${add ? 'Add' : 'Remove'}-MpPreference -ExclusionPath '${dest}'`);
}

//#endregion

//#region mounted node_modules folders

/**
 * Replaces the extracted node_modules folders of the workspace with ones from `attach`, runs the
 * transpile step of the PR jobs on them, and puts the extracted folders back.
 */
async function transpileWith(name: string, attach: (roots: readonly string[]) => void, detach: (roots: readonly string[]) => void): Promise<void> {
	if (!selected('workload')) {
		return;
	}
	const roots = nodeModulesRoots();
	const moved: string[] = [];
	try {
		for (const root of roots) {
			fs.renameSync(path.join(ws, root), path.join(ws, `${root}.nmb`));
			moved.push(root);
		}
		if (await measure('image', `${name}: attach ${roots.length} node_modules folders`, () => attach(roots))) {
			await measure('workload', `transpile, ${name}`, transpile);
		}
	} finally {
		try {
			detach(roots);
		} catch (err) {
			console.log(`::warning::detaching ${name} failed: ${message(err)}`);
		}
		for (const root of moved) {
			try {
				fs.renameSync(path.join(ws, `${root}.nmb`), path.join(ws, root));
			} catch (err) {
				console.log(`::warning::restoring ${root} failed: ${message(err)}`);
			}
		}
	}
}

function linkRoots(base: string, type: 'junction' | 'dir'): (roots: readonly string[]) => void {
	return roots => {
		for (const root of roots) {
			fs.symlinkSync(path.join(base, root), path.join(ws, root), type);
		}
	};
}

function unlinkRoots(roots: readonly string[]): void {
	for (const root of roots) {
		const link = path.join(ws, root);
		if (fs.lstatSync(link, { throwIfNoEntry: false })?.isSymbolicLink()) {
			// Removes the link (or junction) only, never the folder it points to
			fs.unlinkSync(link);
		}
	}
}

function mountRoots(lower: string, kind: 'overlay' | 'bind'): (roots: readonly string[]) => void {
	return roots => {
		const lines = ['set -e'];
		for (const root of roots) {
			const target = path.join(ws, root);
			fs.mkdirSync(target);
			if (kind === 'bind') {
				lines.push(`mount --bind '${path.join(lower, root)}' '${target}'`);
			} else {
				const upper = path.join(temp, 'nmb-overlay', 'upper', root);
				const workdir = path.join(temp, 'nmb-overlay', 'work', root);
				fs.mkdirSync(upper, { recursive: true });
				fs.mkdirSync(workdir, { recursive: true });
				lines.push(`mount -t overlay overlay -o 'lowerdir=${path.join(lower, root)},upperdir=${upper},workdir=${workdir}' '${target}'`);
			}
		}
		const script = path.join(temp, 'nmb-mount.sh');
		fs.writeFileSync(script, lines.join('\n'));
		run('sudo', ['bash', script]);
	};
}

function unmountRoots(roots: readonly string[]): void {
	for (const root of roots) {
		const target = path.join(ws, root);
		spawnSync('sudo', ['umount', target], { stdio: 'inherit' });
		if (fs.existsSync(target) && !fs.readdirSync(target).length) {
			fs.rmdirSync(target);
		}
	}
	fs.rmSync(path.join(temp, 'nmb-overlay'), { recursive: true, force: true });
}

//#endregion

//#region images

async function windowsImage(kind: string): Promise<void> {
	const vhd = imageSource(kind);
	if (!fs.existsSync(vhd)) {
		return;
	}
	const zst = `${vhd}.zst`;
	recordSize(`Dev Drive VHDX, ${kind}`, vhd);
	if (!await measure('build', `Dev Drive VHDX, ${kind}: compress`, () => run('zstd', ['-q', '-3', '-T0', '--long=30', '-f', vhd, '-o', zst]))) {
		return;
	}
	recordSize(`Dev Drive VHDX, ${kind}, zstd`, zst);
	fs.rmSync(vhd);
	// What a PR job would do after downloading the compressed VHDX
	let attached = false;
	try {
		if (!await measure('image', `Dev Drive VHDX, ${kind}: decompress`, () => run('zstd', ['-d', '-q', '--long=31', '-f', zst, '-o', vhd]))) {
			return;
		}
		attached = await measure('image', `Dev Drive VHDX, ${kind}: attach`, () => attachVhd(vhd, 'Y'));
		if (!attached) {
			return;
		}
		await measure('image', `Dev Drive VHDX, ${kind}: trust`, () => {
			run('fsutil', ['devdrv', 'trust', 'Y:']);
			return run('fsutil', ['devdrv', 'query', 'Y:'], { capture: true }).trim().split(/\r?\n/).filter(Boolean).join('; ');
		});
		if (kind === 'dedup') {
			await variant('robocopy /MT:64 from the VHDX', dest => run('robocopy', ['Y:\\', dest, '/E', '/MT:64', '/NFL', '/NDL', '/NJH', '/NJS', '/NP', '/R:0', '/W:0', '/XD', 'System Volume Information', '$RECYCLE.BIN'], { okCodes: [0, 1, 2, 3, 4, 5, 6, 7] }));
			await transpileWith(`junctions to the ${kind} VHDX`, linkRoots('Y:\\', 'junction'), unlinkRoots);
		}
	} finally {
		if (attached) {
			try {
				detachVhd(vhd);
			} catch (err) {
				console.log(`::warning::detaching ${vhd} failed: ${message(err)}`);
			}
		}
		fs.rmSync(vhd, { force: true });
		fs.rmSync(zst, { force: true });
	}
}

async function linuxImages(): Promise<void> {
	const source = imageSource('plain');
	if (!fs.existsSync(source)) {
		return;
	}
	const mount = (type: string, image: string, dir: string, options: string) => {
		run('sudo', ['mkdir', '-p', dir]);
		run('sudo', ['mount', '-t', type, '-o', options, image, dir]);
	};
	const unmount = (dir: string) => spawnSync('sudo', ['umount', dir], { stdio: 'inherit' });
	await measure('image', 'extracted folder: read every file', () => readAll(source));

	if (selected('squashfs')) {
		const image = path.join(temp, 'nmb.squashfs');
		const dir = '/mnt/nmb-squashfs';
		if (await measure('build', 'squashfs (zstd): mksquashfs', () => run('mksquashfs', [source, image, '-noappend', '-comp', 'zstd', '-Xcompression-level', '3', '-b', '1M', '-no-progress', '-quiet']))) {
			recordSize('squashfs image', image);
			if (await measure('image', 'squashfs: mount', () => mount('squashfs', image, dir, 'loop,ro'))) {
				await transpileWith('squashfs + overlayfs', mountRoots(dir, 'overlay'), unmountRoots);
				await measure('image', 'squashfs: read every file', () => readAll(dir));
				unmount(dir);
			}
			fs.rmSync(image, { force: true });
		}
	}

	if (selected('erofs')) {
		const image = path.join(temp, 'nmb.erofs');
		const dir = '/mnt/nmb-erofs';
		if (await measure('build', 'erofs (lz4hc): mkfs.erofs', () => run('mkfs.erofs', ['-zlz4hc', image, source]))) {
			recordSize('erofs image', image);
			if (await measure('image', 'erofs: mount', () => mount('erofs', image, dir, 'loop,ro'))) {
				await transpileWith('erofs + overlayfs', mountRoots(dir, 'overlay'), unmountRoots);
				await measure('image', 'erofs: read every file', () => readAll(dir));
				unmount(dir);
			}
			fs.rmSync(image, { force: true });
		}
	}

	if (selected('ext4')) {
		// The equivalent of the Windows VHDX: an uncompressed file system image, compressed for the cache
		const image = path.join(temp, 'nmb.ext4');
		const zst = `${image}.zst`;
		const dir = '/mnt/nmb-ext4';
		if (await measure('build', 'ext4 image: mkfs.ext4 -d', () => run('mkfs.ext4', ['-q', '-F', '-d', source, image, '24G']))) {
			recordSize('ext4 image', image);
			if (await measure('build', 'ext4 image: compress', () => run('zstd', ['-q', '-3', '-T0', '--long=30', '-f', image, '-o', zst]))) {
				recordSize('ext4 image, zstd', zst);
				fs.rmSync(image);
				run('sync', []);
				if (await measure('image', 'ext4 image: decompress', () => run('zstd', ['-d', '-q', '--long=31', '-f', zst, '-o', image]))
					&& await measure('image', 'ext4 image: mount', () => mount('ext4', image, dir, 'loop'))) {
					await transpileWith('ext4 image + bind mounts', mountRoots(dir, 'bind'), unmountRoots);
					unmount(dir);
				}
			}
			fs.rmSync(image, { force: true });
			fs.rmSync(zst, { force: true });
		}
	}
}

async function macImages(): Promise<void> {
	const source = imageSource('plain');
	if (!fs.existsSync(source)) {
		return;
	}
	const dir = path.join(temp, 'nmb-mount');
	const shadow = path.join(temp, 'nmb.shadow');
	const attach = (image: string, ...options: string[]) => {
		fs.mkdirSync(dir, { recursive: true });
		run('hdiutil', ['attach', '-quiet', '-noverify', '-nobrowse', ...options, '-mountpoint', dir, image]);
	};
	const detach = () => spawnSync('hdiutil', ['detach', '-force', dir], { stdio: 'inherit' });
	const ulfo = path.join(temp, 'nmb-ulfo.dmg');
	await measure('image', 'extracted folder: read every file', () => readAll(source));

	if (!await measure('build', 'DMG ULFO (lzfse): hdiutil create', () => run('hdiutil', ['create', '-quiet', '-ov', '-srcfolder', source, '-volname', 'nmb', '-fs', 'APFS', '-format', 'ULFO', ulfo]))) {
		return;
	}
	recordSize('DMG ULFO', ulfo);

	if (selected('dmg')) {
		if (await measure('image', 'DMG ULFO: attach with a shadow file (writable)', () => attach(ulfo, '-shadow', shadow))) {
			await transpileWith('symlinks to the DMG ULFO', linkRoots(dir, 'dir'), unlinkRoots);
			detach();
		}
		fs.rmSync(shadow, { force: true });
		if (await measure('image', 'DMG ULFO: attach read-only', () => attach(ulfo, '-readonly'))) {
			await measure('image', 'DMG ULFO: read every file', () => readAll(dir));
			detach();
		}

		const udzo = path.join(temp, 'nmb-udzo.dmg');
		if (await measure('build', 'DMG UDZO (zlib): hdiutil convert', () => run('hdiutil', ['convert', '-quiet', '-ov', ulfo, '-format', 'UDZO', '-o', udzo]))) {
			recordSize('DMG UDZO', udzo);
			if (await measure('image', 'DMG UDZO: attach read-only', () => attach(udzo, '-readonly'))) {
				await measure('image', 'DMG UDZO: read every file', () => readAll(dir));
				detach();
			}
			fs.rmSync(udzo, { force: true });
		}
	}

	if (selected('sparseimage')) {
		// The equivalent of the Windows VHDX: an uncompressed, writable image, compressed for the cache
		const sparse = path.join(temp, 'nmb.sparseimage');
		const zst = `${sparse}.zst`;
		if (await measure('build', 'APFS sparse image: hdiutil convert', () => run('hdiutil', ['convert', '-quiet', '-ov', ulfo, '-format', 'UDSP', '-o', sparse]))) {
			recordSize('APFS sparse image', sparse);
			if (await measure('build', 'APFS sparse image: compress', () => run('zstd', ['-q', '-3', '-T0', '--long=30', '-f', sparse, '-o', zst]))) {
				recordSize('APFS sparse image, zstd', zst);
				fs.rmSync(sparse);
				run('sync', []);
				if (await measure('image', 'APFS sparse image: decompress', () => run('zstd', ['-d', '-q', '--long=31', '-f', zst, '-o', sparse]))
					&& await measure('image', 'APFS sparse image: attach', () => attach(sparse))) {
					await transpileWith('symlinks to the APFS sparse image', linkRoots(dir, 'dir'), unlinkRoots);
					detach();
				}
			}
			fs.rmSync(sparse, { force: true });
			fs.rmSync(zst, { force: true });
		}
	}
	fs.rmSync(ulfo, { force: true });
}

//#endregion

function captureEnvironment(): void {
	const cpus = os.cpus();
	environment['CPUs'] = `${cpus.length} x ${cpus[0]?.model ?? 'unknown'}`;
	environment['Memory'] = `${(os.totalmem() / 2 ** 30).toFixed(0)} GB`;
	environment['OS'] = `${os.type()} ${os.release()}`;
	environment['Node.js'] = process.version;
	try {
		const disk = fs.statfsSync(ws);
		environment['Free disk'] = `${(disk.bavail * disk.bsize / 2 ** 30).toFixed(0)} GB`;
	} catch {
		// not supported
	}
	environment['zstd'] = tryFirstLine('zstd', ['--version']);
	if (isWindows) {
		environment['7-Zip'] = tryFirstLine('7z', ['i']);
		environment['bsdtar'] = tryFirstLine(BSDTAR, ['--version']);
		environment['GNU tar'] = tryFirstLine(GNUTAR, ['--version']);
		try {
			environment['Defender'] = pwsh('Get-MpComputerStatus | ForEach-Object { "RealTimeProtection=$($_.RealTimeProtectionEnabled) Mode=$($_.AMRunningMode)" }', true).trim();
		} catch (err) {
			environment['Defender'] = message(err);
		}
	} else {
		environment['tar'] = tryFirstLine('tar', ['--version']);
	}
	environment['Today\'s archive'] = formatBytes(fs.statSync(todayArchive).size);
}

async function main(): Promise<void> {
	fs.mkdirSync(work, { recursive: true });
	captureEnvironment();
	writeResults(false);

	// Today's restore, into the workspace like the PR jobs: its files are the input of all the rest
	await measure('today', 'extract into the workspace', () => extractToday(ws));
	await measure('build', 'list the files', () => {
		run(process.execPath, [path.join(ws, 'build/azure-pipelines/common/listNodeModules.ts'), listFile]);
		return `${fs.readFileSync(listFile, 'utf8').split('\n').filter(Boolean).length} files in ${nodeModulesRoots().length} node_modules folders`;
	});
	await measure('build', 'pack the tar.zst archives', () => run(process.execPath, [archiveTool, 'pack', '--root', ws, '--list', listFile,
		...ARCHIVES.flatMap(({ name, flags }) => ['--out', flags ? `${flags}@${archive(name)}` : archive(name)])]));
	recordSize('today\'s archive', todayArchive);
	for (const { name } of ARCHIVES) {
		recordSize(`${name}.tar.zst`, archive(name));
	}
	if (!isWindows) {
		await measure('build', 'count the entries of today\'s archive', () => countArchive(todayArchive));
	}
	if (isWindows && selected('7z store')) {
		if (await measure('build', '7z store archive', () => run('7z', ['a', '-mx0', '-bso0', '-bsp0', store7z, `@${listFile}`], { cwd: ws }))) {
			recordSize('store.7z', store7z);
		}
	}

	if (selected('workload')) {
		await measure('workload', 'transpile, extracted node_modules (1st run)', transpile);
		await measure('workload', 'transpile, extracted node_modules (2nd run)', transpile);
	}

	if (isWindows && selected('7z test')) {
		await measure('restore', '7z test: decode only, no files', () => run('7z', ['t', '-bso0', '-bsp0', todayArchive]));
	}
	await variant('today', extractToday);
	if (isWindows) {
		await variant('today, Defender exclusion', extractToday, { before: dest => defenderExclusion(dest, true), after: dest => defenderExclusion(dest, false) });
		if (fs.existsSync(store7z)) {
			await variant('7z store: no decompression', dest => run('7z', ['x', store7z, '-aoa', `-o${dest}`]));
		}
		await variant('GNU tar + zstd, plain', dest => run(GNUTAR, ['--force-local', '--use-compress-program', 'zstd -d --long=31', '-xf', slash(archive('plain')), '-C', slash(dest)]));
		await variant('bsdtar + zstd pipe, plain', dest => shell(`zstd -d -q --long=31 -c "${archive('plain')}" | "${BSDTAR}" -xf - -C ${slash(dest)}`));
		await variant('bsdtar native zstd, plain', dest => run(BSDTAR, ['-xf', slash(archive('plain')), '-C', slash(dest)]));
	} else {
		await variant('tar + zstd, plain', dest => run('tar', ['--use-compress-program=zstd -d -T0 --long=31', '-xf', archive('plain')], { cwd: dest }));
		if (isMac) {
			await variant('today, gtar', dest => run('gtar', ['--use-compress-program=zstd -d -T0', '-xf', todayArchive], { cwd: dest }));
		}
	}
	for (const concurrency of CONCURRENCY_SWEEP) {
		await variant(`node plain c${concurrency}`, dest => nodeExtract('plain', dest, concurrency), { keepAs: concurrency === 64 ? imageSource('plain') : undefined });
	}
	// The other archives use the concurrency that restored the plain archive the fastest
	const best = CONCURRENCY_SWEEP
		.map(concurrency => ({ concurrency, row: rows.find(row => row.name === `node plain c${concurrency}` && !row.error) }))
		.filter(({ row }) => row?.seconds !== undefined)
		.sort((a, b) => a.row!.seconds! - b.row!.seconds!)[0]?.concurrency ?? 16;
	environment['Best concurrency'] = String(best);
	await variant(`node plain c${best}, node:zlib zstd`, dest => nodeExtract('plain', dest, best, 'node'));
	for (const { name } of ARCHIVES.filter(({ name }) => name !== 'plain')) {
		await variant(`node ${name} c${best}`, dest => nodeExtract(name, dest, best), { keepAs: name === 'dedup' && isWindows ? imageSource('dedup') : undefined });
	}
	await variant('node dedup c256', dest => nodeExtract('dedup', dest, 256));
	if (isWindows) {
		await variant(`node plain c${best}, Defender exclusion`, dest => nodeExtract('plain', dest, best), { before: dest => defenderExclusion(dest, true), after: dest => defenderExclusion(dest, false) });
	}

	if (isWindows) {
		await windowsImage('plain');
		await windowsImage('dedup');
	} else if (isMac) {
		await macImages();
	} else {
		await linuxImages();
	}
	fs.rmSync(imageSource('plain'), { recursive: true, force: true });

	// Repeat two variants to see how much the runner drifts during the benchmark
	await variant('today (repeat)', extractToday);
	await variant(`node plain c${best} (repeat)`, dest => nodeExtract('plain', dest, best));
	if (selected('workload')) {
		await measure('workload', 'transpile, extracted node_modules (3rd run)', transpile);
	}
}

main().catch(err => {
	console.log(`::error::${message(err)}`);
	process.exitCode = 1;
}).finally(() => writeResults(true));
